package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)

	var n int
	var k int64
	fmt.Fscan(in, &n, &k)

	ways := make([]int64, n+1)
	ways[0] = 1
	if n >= 1 {
		ways[1] = 1
	}
	for i := 2; i <= n; i++ {
		ways[i] = ways[i-1] + ways[i-2]
	}

	ans := make([]int, 0, n)
	for pos := 1; pos <= n; {
		remaining := n - pos + 1
		singleCount := ways[remaining-1]

		if remaining == 1 || k <= singleCount {
			ans = append(ans, pos)
			pos++
		} else {
			k -= singleCount
			ans = append(ans, pos+1, pos)
			pos += 2
		}
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	for i, value := range ans {
		if i > 0 {
			fmt.Fprint(out, " ")
		}
		fmt.Fprint(out, value)
	}
	fmt.Fprintln(out)
}

